using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Invoices.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Entities;namespace Namaa.Application.Invoices.Commands.CreateInvoice;public sealed class CreateInvoiceCommandHandler(IInvoiceRepository repository,IUserRepository users,IApplicationDbContext db):IRequestHandler<CreateInvoiceCommand,Result<InvoiceDto>>{public async Task<Result<InvoiceDto>>Handle(CreateInvoiceCommand request,CancellationToken cancellationToken){if(await repository.ExistsByNumberAsync(request.InvoiceNumber,cancellationToken))return Result.Failure<InvoiceDto>(InvoiceErrors.DuplicateNumber);if(!await users.ExistsByIdAsync(request.CreatedByUserId,cancellationToken))return Result.Failure<InvoiceDto>(new Error("Invoices.UserNotFound","The user was not found.",ErrorType.NotFound));var e=Invoice.Create(request.InvoiceNumber,request.IssueDate,request.CreatedByUserId,request.DueDate,request.ProjectId,request.CustomerId,request.Notes);await repository.AddAsync(e,cancellationToken);await db.SaveChangesAsync(cancellationToken);return Result.Success(InvoiceDto.FromEntity(e));}}
